/**
* Generate Boost test fixtures.
*
* ## Notes
*
* -   Run this script from the directory in which fixtures should be written.
*
*/
#include <stdlib.h>
#include <stdio.h>
#include <boost/random/mersenne_twister.hpp>
#include <boost/random/uniform_int_distribution.hpp>
#include <boost/random/uniform_real_distribution.hpp>
#include <boost/math/special_functions/powm1.hpp>

using boost::random::uniform_real_distribution;
using boost::random::uniform_int_distribution;
using boost::random::mt19937;

// Define a new pseudorandom number generator:
mt19937 rng;

/**
 * Generates a linearly spaced numeric array of floats.
 */
void linspace_f32( float *out, const unsigned int len, const float start, const float end ) {
  	unsigned int i;
  	float incr;

  	incr = ( end-start ) / ( len-1 );
  	for ( i = 0; i < len-1; i++ ) {
  		out[ i ] = start + ( incr*i );
  	}
  	out[ i ] = end;
}

/**
 * Generates a linearly spaced numeric array of integers.
 */
void linspace_i32( int *out, const unsigned int len, const int start, const int end ) {
  	unsigned int i;
  	int incr;

  	incr = ( end-start ) / ( len-1 );
  	for ( i = 0; i < len-1; i++ ) {
  		out[ i ] = start + ( incr*i );
  	}
  	out[ i ] = end;
}

/**
 * Generates an array of pseudorandom floats drawn from a uniform distribution.
 */
void rand_array_f32( float *out, const unsigned int len, const float a, const float b ) {
  	unsigned int i;
  	uniform_real_distribution<float> randu( a, b );

  	for ( i = 0; i < len; i++ ) {
  		out[ i ] = randu( rng );
  	}
}

/**
 * Generates an array of pseudorandom integers drawn from a uniform distribution.
 */
void rand_array_i32( int *out, const unsigned int len, const int a, const int b ) {
  	unsigned int i;
  	uniform_int_distribution<> randi( a, b );

  	for ( i = 0; i < len; i++ ) {
  		out[ i ] = randi( rng );
  	}
}

/**
 * Casts an array of integers to an array of floats.
 */
void i32_to_f32( float *out, int *x, unsigned int len ) {
  	unsigned int i;
  	for ( i = 0; i < len; i++ ) {
  		out[ i ] = (float)x[ i ];
  	}
}

/**
 * Casts an array of floats to an array of integers.
 */
void f32_to_i32( int *out, float *x, unsigned int len ) {
  	unsigned int i;
  	for ( i = 0; i < len; i++ ) {
  		out[ i ] = (int)x[ i ];
  	}
}

/**
 * Writes an array of floats to a file as a series of comma-separated values.
 */
void write_array_f32( FILE *f, const float *x, const unsigned int len ) {
  	unsigned int i;
  	for ( i = 0; i < len; i++ ) {
  		fprintf( f, "%.9g", (double)x[ i ] );
  		if ( i < len-1 ) {
  			fprintf( f, "," );
  		}
  	}
}

/**
 * Writes an array of integers to a file as a series of comma-separated values.
 */
void write_array_i32( FILE *f, const int *x, const unsigned int len ) {
  	unsigned int i;
  	for ( i = 0; i < len; i++ ) {
  		fprintf( f, "%d", x[ i ] );
  		if ( i < len-1 ) {
  			fprintf( f, "," );
  		}
  	}
}

/**
 * Writes a named array of floats to a file as JSON.
 */
void write_named_array_f32( FILE *f, const char *name, const float *x, const unsigned int len ) {
  	fprintf( f, "\"%s\":[", name );
  	write_array_f32( f, x, len );
  	fprintf( f, "]" );
}

/**
 * Writes a named array of integers to a file as JSON.
 */
void write_named_array_i32( FILE *f, const char *name, const int *x, const unsigned int len ) {
  	fprintf( f, "\"%s\":[", name );
  	write_array_i32( f, x, len );
  	fprintf( f, "]" );
}

/**
 * Writes data to a file as JSON.
 */
void write_data_as_json( FILE *f, const float *b, const float *x, const float *y, const unsigned int len ) {
  	fprintf( f, "{" );
  	write_named_array_f32( f, "b", b, len );
  	fprintf( f, "," );
  	write_named_array_f32( f, "x", x, len );
  	fprintf( f, "," );
  	write_named_array_f32( f, "expected", y, len );
  	fprintf( f, "}" );
}

/**
 * Generates test fixtures.
 */
void generate( float *b, float *x, const unsigned int len, const char *name ) {
  	unsigned int i;
  	float *y;
  	FILE *f;

  	y = (float*) malloc( len * sizeof(float) );
  	if ( y == NULL ) {
  		printf( "Error allocating memory.\n" );
  		exit( 1 );
  	}

  	for ( i = 0; i < len; i++ ) {
  		y[ i ] = (float)boost::math::powm1( (double)b[ i ], (double)x[ i ] );
  	}

  	f = fopen( name, "w" );
  	if ( f == NULL ) {
  		printf( "Error opening file.\n" );
  		exit( 1 );
  	}
  	write_data_as_json( f, b, x, y, len );
  	fclose( f );
  	free( y );
}

/**
 * Main execution sequence.
 */
int main( void ) {
  	unsigned int len;
  	float *b;
  	float *x;

  	len = 2000;

  	b = (float*) malloc( len * sizeof(float) );
  	if ( b == NULL ) {
  		printf( "Error allocating memory.\n" );
  		exit( 1 );
  	}
  	x = (float*) malloc( len * sizeof(float) );
  	if ( x == NULL ) {
  		printf( "Error allocating memory.\n" );
  		exit( 1 );
  	}

  	// Keep values in a range where float32 expected values are mostly finite/stable:
  	rand_array_f32( b, len, 0.5f, 10.0f );
  	rand_array_f32( x, len, -10.0f, 10.0f );
  	generate( b, x, len, "output.json" );

  	free( b );
  	free( x );
  	return 0;
}